// Hai lượt cùng chọn một video (bấm hai lần liền, hoặc lịch chạy đúng lúc bấm): cả hai ghi khoá (posted_at) rồi đợi vài giây.
// Lượt ghi sau cùng giữ video; lượt kia thấy khoá đã khác thì dừng, không gửi trùng.
// Không đọc lại được dòng, hoặc posted_at không còn dạng ISO (Sheet tự đổi định dạng), thì không kiểm được: chạy tiếp như trước.
const me = $('Lấy 1 video').first().json;
const now = $input.all().map((i) => i.json).find((r) => String(r.id) === String(me.id));
const mine = DateTime.fromISO(String(me.lock ?? ''));
const seen = DateTime.fromISO(String(now?.posted_at ?? ''));
if (now && mine.isValid && seen.isValid && seen.toMillis() !== mine.toMillis()) return [];
return [{ json: me }];

const r = $input.first().json;
if (!r.access_token) {
  throw new Error('Không làm mới được token TikTok: ' + (r.error_description || r.error || JSON.stringify(r)) +
    '. Chạy lại workflow "TikTok - Kết nối".');
}
return [{ json: { access_token: r.access_token, refresh_token: r.refresh_token } }];

// TikTok nhận video theo khúc 5–64 MB, khúc cuối gánh phần dư (tối đa 128 MB).
const CHUNK = 10 * 1024 * 1024;
const size = Number($input.first().json.size);
if (!size) throw new Error('Không đọc được kích thước video trên Drive');
const count = Math.max(1, Math.floor(size / CHUNK));
return [{ json: { video_size: size, chunk_size: count === 1 ? size : CHUNK, total_chunk_count: count } }];

const init = $input.first().json;
const { upload_url, publish_id } = init.data ?? {};
if (!upload_url) throw new Error('TikTok không trả upload_url: ' + JSON.stringify(init.error ?? init));
const { video_size: size, chunk_size: chunk, total_chunk_count: count } = $('Tính số khúc').first().json;
const fileId = $('Lấy 1 video').first().json.video_file_id;
return Array.from({ length: count }, (_, i) => {
  const start = i * chunk;
  const end = (i === count - 1 ? size : start + chunk) - 1;
  return { json: { fileId, upload_url, publish_id, part: i + 1, bytes: `bytes=${start}-${end}`, range: `bytes ${start}-${end}/${size}` } };
});

// TikTok cần thêm thời gian xử lý video lớn: kiểm tra lại tối đa 10 lần, cách nhau 30 giây.
const d = $input.first().json.data ?? {};
if (d.status === 'FAILED') throw new Error('TikTok báo lỗi: ' + (d.fail_reason || 'không rõ'));
const processing = String(d.status ?? '').startsWith('PROCESSING');
return [{ json: { status: d.status ?? 'không rõ', publish_id: $('Chia khúc').first().json.publish_id, done: !processing || $runIndex >= 9 } }];

const cfg = $('Cấu hình TikTok').first().json;
// Chưa điền bot Telegram thì bỏ qua bước nhắn tin.
