const r = $('Lấy 1 video').first().json;
const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
// Tên ngắn của truyện, như storyNameFromTitle của Story Studio: dòng đầu caption TikTok ("Tên truyện | Phần 1/5"),
// hoặc tên rút từ tiêu đề khi caption cũ còn tiêu đề dài.
const TITLE_TAGS = /\[[^\]]*\]|【[^】]*】|\([^)]*\)|#\S*|\b(cre|credit|nguồn|source)\s*:.*$|\d[\d.,]*\s*[kmb]?\s*(views?|lượt xem|reactions?|likes?|lượt thích|comments?|bình luận|shares?)/giu;
const TITLE_SEPARATORS = /\s+[-–—]\s+|\s*[|·•]\s*|[:.]\s+/u;
const TITLE_NOISE = /^(\d+|full( bộ)?|trọn bộ|\d+\s*(phút|giờ|tiếng)|(tập|phần|part|ep)\s*\d+|.*\b(audio|official|channel|radio|podcast)\b.*|truyện (ngắn|audio|ma|hay|kể|kinh dị|ngôn tình|cổ tích|trinh thám)\b.*)$/iu;
const nameFromTitle = (title) => {
  const pieces = String(title ?? '').replace(TITLE_TAGS, ' ').split(TITLE_SEPARATORS).map((s) => s.replace(/["“”'‘’]/g, '').trim()).filter(Boolean);
  return pieces.find((s) => !TITLE_NOISE.test(s)) ?? pieces.join(' ');
};
const PART_SUFFIX = /\s*(\|\s*Phần\s*\d+\s*\/\s*\d+|\(trọn bộ\))\s*$/iu;
const NAME_MAX = 45;
/** Tên ngắn của truyện của một dòng trong Sheet. Dòng YouTube không lấy caption (đó là mô tả YouTube). */
const shortName = (r) => {
  const line = r.format === 'youtube' ? '' : String(r.post_description ?? '').split('\n')[0].replace(PART_SUFFIX, '').trim();
  for (const c of [line, nameFromTitle(line), nameFromTitle(r.post_title), nameFromTitle(r.title), String(r.title ?? '').trim()]) {
    if (c && c.length <= NAME_MAX) return c;
  }
  const t = line || String(r.title || r.id || '');
  return t.length > NAME_MAX ? `${t.slice(0, NAME_MAX - 1).replace(/\s+\S*$/, '')}…` : t;
};
const s = $('Đánh giá').last().json;
// Caption TikTok: tên ngắn của truyện kèm số phần, rồi tối đa 5 hashtag (TikTok chỉ nhận 5), không có đoạn mô tả.
const name = `${shortName(r)}${r.part ? ` | Phần ${r.part}/${r.total_parts}` : ' (trọn bộ)'}`;
const isTags = (l) => l.trim() && l.trim().split(/\s+/).every((w) => w.startsWith('#'));
const tagLine = String(r.hashtags ?? '').trim() || String(r.post_description ?? '').split('\n').filter(isTags).join(' ');
const tags = tagLine.split(/\s+/).filter((t) => t.startsWith('#') && t.length > 1).slice(0, 5).join(' ');
const caption = [name, tags].filter(Boolean).join('\n\n');
const block = (label, text) => text ? [`${label} (chạm để copy):`, `<pre>${esc(text)}</pre>`, ''] : [];
const sec = Math.round(Number(r.duration_sec) || 0);
const text = [
  `🎬 <b>${esc(shortName(r))}</b>${r.part ? ` · Phần ${r.part}/${r.total_parts}` : ' · Trọn bộ'}`,
  s.status === 'SEND_TO_USER_INBOX'
    ? '✅ Đã vào hộp thư TikTok, mở app để đăng'
    : `⏳ TikTok vẫn đang xử lý (${esc(s.status)}), vài phút nữa video sẽ vào hộp thư`,
  `⏱ ${Math.floor(sec / 60)}:${String(sec % 60).padStart(2, '0')}`,
  '',
  ...block('📌 <b>Tên</b>', name),
  ...block('#️⃣ <b>Hashtag</b>', tags),
  ...block('📋 <b>Caption đầy đủ</b>, gồm tên và hashtag', caption),
].join('\n').trim();
return [{ json: { payload: {
  chat_id: cfg.telegram_chat_id, parse_mode: 'HTML', text, link_preview_options: { is_disabled: true },
  reply_markup: { inline_keyboard: [[
    { text: '✅ Đã đăng', callback_data: `posted|${r.id}` },
    { text: '⏭ Bỏ qua', callback_data: `skip|${r.id}` },
  ], [
    { text: '⏩ Đã đăng, gửi tiếp', callback_data: `postnext|${r.id}` },
  ]] },
} } }];

