const rows = $('Đọc Sheet').all().map((i) => i.json);
const flags = {};
for (const f of $('Đọc cài đặt').all().map((i) => i.json)) if (f.key) flags[f.key] = String(f.value ?? '');
// Tab CaiDat chưa có thì mọi thứ để mặc định; đọc lỗi kiểu khác thì không đoán truyện nào đang chạy hay lịch có tạm dừng không.
const errorText = (e) => (typeof e === 'string' ? e : e?.message ?? JSON.stringify(e));
const flagError = $('Đọc cài đặt').all().map((i) => i.json.error).find((e) => e && !/not found|unable to parse range/i.test(errorText(e)));
