};
const label = (r) => `${esc(shortName(r))}${r.part ? ` · Phần ${r.part}/${r.total_parts}` : r.kind === 'full' ? ' · Trọn bộ' : ''}`;
const sent = DateTime.fromISO(String(w.posted_at ?? ''));
const text = [
  '⏰ <b>Nhắc đăng</b>: video này nằm trong hộp thư TikTok hơn 3 giờ rồi',
  `🎬 ${label(w)}${sent.isValid ? ` (gửi lúc ${sent.setZone('Asia/Ho_Chi_Minh').toFormat('HH:mm')})` : ''}`,
  waitingCount > 1 ? `Còn ${waitingCount} video trong hộp thư chưa đăng.` : null,
  row ? `\nĐang chờ gửi tiếp: ${label(row)}` : null,
  '\nĐăng xong thì bấm ✅ Đã đăng (ở đây hoặc ở tin trước). Bấm ⏩ để nhận video kế tiếp ngay.',
].filter((l) => l !== null).join('\n');
return [{ json: { payload: {
  chat_id: cfg.telegram_chat_id, parse_mode: 'HTML', text,
  reply_markup: { inline_keyboard: [[
    { text: '✅ Đã đăng', callback_data: `posted|${w.id}` },
    { text: '⏭ Bỏ qua', callback_data: `skip|${w.id}` },
  ], [
    { text: '⏩ Đã đăng, gửi tiếp', callback_data: `postnext|${w.id}` },
  ]] },
} } }];

const cfg = $('Cấu hình TikTok').first().json;
// Chưa điền bot Telegram thì bỏ qua bước nhắn tin.
if (!cfg.telegram_bot_token || cfg.telegram_bot_token.startsWith('DAN_')) return [];
return [{ json: { payload: { chat_id: cfg.telegram_chat_id, text: $json.text } } }];
